109:       if (this.announcement.life <= 0) this.announcement = null;
110:     }
111:     this.shake *= 0.88;
112:     if (this.shake < 0.15) this.shake = 0;
113:     this.screenFlash = Math.max(0, this.screenFlash - 0.035);
114:     this.camera.punch *= 0.9;
115: 
116:     if (this.phase === 'countdown') {
117:       this.countdown++;
118:       this.updateFightersCountdown();
119:       this.updateCamera();
120:       this.tickCountdown();
121:       return;
122:     }
123: 
124:     if (this.phase === 'over') {
125:       this.overTimer--;
126:       this.updateFightersIdle(humanInputs);
127:       this.updateProjectiles();
128:       this.updateCamera();
129:       if (this.overTimer <= 0) this.finish();
130:       return;
131:     }
132: 
133:     if (this.phase === 'ended') {
134:       this.updateCamera();
135:       return;
136:     }
137: 
138:     this.clock++;
139: 
140:     if (this.hitstop > 0) {
141:       this.hitstop--;
142:       this.updateCamera();
143:       return;
144:     }
145: 
146:     for (const f of this.fighters) {
147:       let input = EMPTY_INPUT;
148:       if (!f.eliminated && f.koTimer <= 0) {
149:         if (f.kind === 'cpu') {
150:           const brain = this.ais.find((a) => a.f === f);
151:           input = brain ? brain.update(this) : EMPTY_INPUT;
152:         } else {
153:           input = humanInputs[f.slot] || EMPTY_INPUT;
154:         }
155:       }
156:       f.update(input, this);
157:     }
158:     this.updateProjectiles();
159:     this.checkEnd();
160:     this.updateCamera();
161:   }
162: 
163:   updateFightersCountdown() {
164:     for (const f of this.fighters) {
165:       if (f.eliminated) continue;
166:       f.update(EMPTY_INPUT, this);
167:     }
168:   }
