193:   checkEnd() {
194:     if (this.ending) return;
195:     const alive = this.fighters.filter((f) => f.stocks > 0 && !f.eliminated);
196:     if (alive.length <= 1 && this.fighters.length >= 2) {
197:       this.ending = true;
198:       this.phase = 'over';
199:       this.overTimer = 112;
200:       const winner = alive[0];
201:       for (const f of alive) f.invincible = Math.max(f.invincible, 220);
202:       if (winner) {
203:         this.announce('GAME!', `${winner.tag} WINS`, winner.color, 110);
204:       } else {
205:         this.announce('GAME!', 'DOUBLE KO', '#ffd75e', 110);
206:       }
207:       this.screenFlash = 0.4;
208:       this.flashColor = '#ffffff';
209:       for (let i = 0; i < 30; i++) {
210:         this.addParticle({
211:           type: 'confetti', x: (Math.random() - 0.5) * 900, y: -420 - Math.random() * 300,
212:           vx: (Math.random() - 0.5) * 3, vy: 1 + Math.random() * 3, size: 4 + Math.random() * 5,
213:           color: ['#ffd75e', '#ff7a3d', '#ff3d8b', '#45e3ff', '#b6ff5c'][i % 5],
214:           life: 180 + Math.random() * 80, maxLife: 240, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.2,
215:         });
216:       }
217:       audio.win();
218:     }
219:   }
