228:   buildResults() {
229:     const survivors = this.fighters
230:       .filter((f) => f.stocks > 0 && !f.eliminated)
231:       .sort((a, b) => b.stocks - a.stocks || a.damage - b.damage);
232:     const eliminated = this.elimOrder
233:       .slice()
234:       .reverse()
235:       .map((slot) => this.fighters.find((f) => f.slot === slot))
236:       .filter(Boolean);
237:     const ordered = [...survivors, ...eliminated];
238:     const rows = ordered.map((f, i) => ({
239:       slot: f.slot,
240:       tag: f.tag,
241:       charId: f.charId,
242:       charName: f.char.name,
243:       kind: f.kind,
244:       color: f.color,
245:       placement: i + 1,
246:       stocks: f.stocks,
247:       damage: Math.round(f.damage),
248:       kos: f.stats.kos,
249:       falls: f.stats.falls,
250:       dealt: Math.round(f.stats.dealt),
251:     }));
252:     return {
253:       rows,
254:       winner: survivors[0] || null,
255:       winnerSlot: survivors[0] ? survivors[0].slot : null,
256:       duration: this.clock,
257:       stage: this.stage,
258:     };
259:   }
