293:     this.ring(defender.x, defender.y - 45, '#ffffff', 56);
294:     this.burst(defender.x, defender.y - 45, defender.char.palette.glow, 18, 6);
295:     this.popup(defender.x, defender.y - 95, 'COUNTER!', defender.char.palette.glow, 1.1);
296:     this.screenFlash = Math.max(this.screenFlash, 0.3);
