301:   onKO(fighter, killer) {
302:     const x = clamp(fighter.x, BLAST.left + 40, BLAST.right - 40);
303:     const y = clamp(fighter.y, BLAST.top + 60, BLAST.bottom - 40);
304:     for (let i = 0; i < 26; i++) {
305:       this.addParticle({
306:         type: 'spark', x, y,
307:         vx: (Math.random() - 0.5) * 24, vy: (Math.random() - 0.5) * 24,
308:         life: 28 + Math.random() * 28, maxLife: 56, size: 2 + Math.random() * 5,
309:         color: ['#ffffff', '#ffd75e', '#ff7a3d', fighter.color][i % 4], grav: 0.25,
310:       });
311:     }
312:     for (let i = 0; i < 8; i++) {
313:       this.addParticle({
314:         type: 'ring', x, y, vx: 0, vy: 0, life: 26 + i * 4, maxLife: 56,
315:         size: 20 + i * 14, color: i % 2 ? fighter.color : '#ffffff', grav: 0,
316:       });
317:     }
318:     this.addParticle({
319:       type: 'beam', x, y, vx: 0, vy: 0, life: 38, maxLife: 38, size: 220,
320:       color: fighter.color, grav: 0, rot: Math.atan2(y, x) + Math.PI / 2,
321:     });
322:     this.popup(x, y - 30, 'KO!', '#fff', 1.6);
323:     this.shake = 18;
324:     this.screenFlash = 0.72;
325:     this.flashColor = '#fff6e6';
326:     this.hitstop = Math.max(this.hitstop, 14);
327:     this.camera.punch = 0.1;
328:     audio.ko();
329:     if (killer && killer !== fighter) killer.stats.kos++;
330:     if (fighter.stocks <= 0) {
331:       this.elimOrder.push(fighter.slot);
332:       this.announce('ELIMINATED', `${fighter.tag} · ${fighter.char.name}`, fighter.color, 60);
333:     } else {
334:       this.announce('KO!', `${fighter.tag} LOSES A STOCK`, fighter.color, 46);
335:     }
336:   }
