442:   // -------------------------------------------------------------------------
443:   updateCamera(instant = false) {
444:     const live = this.fighters.filter((f) => f.alive && f.koTimer <= 0);
445:     const vw = this.view.w || 1280;
446:     const vh = this.view.h || 720;
447:     const base = vh / 720;
448:     let minX = Infinity;
449:     let maxX = -Infinity;
450:     let minY = Infinity;
451:     let maxY = -Infinity;
452:     if (live.length) {
453:       for (const f of live) {
454:         minX = Math.min(minX, f.x);
455:         maxX = Math.max(maxX, f.x);
456:         minY = Math.min(minY, f.y - 100);
457:         maxY = Math.max(maxY, f.y);
458:       }
459:     } else {
460:       minX = -300; maxX = 300; minY = -260; maxY = 0;
461:     }
462:     const spreadX = Math.max(520, maxX - minX + 480);
463:     const spreadY = Math.max(420, maxY - minY + 380);
464:     let zoomX = (vw * 0.92) / (spreadX * base);
465:     let zoomY = (vh * 0.82) / (spreadY * base);
466:     let zoom = Math.min(zoomX, zoomY, 1.16);
467:     zoom = clamp(zoom, 0.42, 1.16);
468:     if (live.length === 1) zoom = Math.min(zoom, 0.95);
469: 
470:     const tx = (minX + maxX) / 2;
471:     const ty = (minY + maxY) / 2 - 24;
472:     const ease = instant ? 1 : 0.09;
473:     this.camera.x += (tx - this.camera.x) * ease;
474:     this.camera.y += (ty - this.camera.y) * ease;
475:     this.camera.zoom += (zoom - this.camera.zoom) * (instant ? 1 : 0.06);
476:   }
477: 
478:   // -------------------------------------------------------------------------
479:   addParticle(p) {
480:     if (this.particles.length > 420) this.particles.shift();
481:     this.particles.push(p);
482:   }
483: 
484:   updateParticles() {
485:     const keep = [];
486:     for (const p of this.particles) {
487:       p.life--;
488:       if (p.life <= 0) continue;
489:       p.vy += p.grav || 0;
490:       p.vx *= p.drag ?? 0.98;
491:       p.x += p.vx;
492:       p.y += p.vy;
493:       if (p.vr) p.rot = (p.rot || 0) + p.vr;
494:       if (p.type === 'ring') p.size += p.grow || 6;
495:       if (p.type === 'confetti' && p.y > 420) p.life = 0;
496:       keep.push(p);
497:     }
498:     this.particles = keep;
499:   }
500: 
501:   updatePopups() {
502:     const keep = [];
503:     for (const p of this.popups) {
504:       p.life--;
505:       p.y -= 1.1;
506:       p.vy += 0.02;
507:       if (p.life > 0) keep.push(p);
508:     }
509:     this.popups = keep;
510:   }
511: 
512:   dust(x, y, dir, color = '#e9e4ff', count = 4) {
513:     for (let i = 0; i < count; i++) {
514:       this.addParticle({
515:         type: 'dust', x: x + (Math.random() - 0.5) * 12, y: y - Math.random() * 6,
516:         vx: (dir || (Math.random() - 0.5)) * (0.6 + Math.random() * 2.2),
517:         vy: -Math.random() * 1.8, life: 18 + Math.random() * 16, maxLife: 34,
518:         size: 6 + Math.random() * 9, color, grav: -0.015, drag: 0.94,
519:       });
520:     }
521:   }
522: 
523:   burst(x, y, color, count = 8, power = 4) {
524:     for (let i = 0; i < count; i++) {
525:       const a = Math.random() * Math.PI * 2;
526:       const s = power * (0.4 + Math.random());
527:       this.addParticle({
528:         type: Math.random() < 0.6 ? 'spark' : 'star',
529:         x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 0.6,
530:         life: 14 + Math.random() * 22, maxLife: 36, size: 2 + Math.random() * 4,
531:         color, grav: 0.12, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.5,
532:       });
533:     }
534:   }
535: 
536:   ring(x, y, color, size = 30) {
537:     this.addParticle({
538:       type: 'ring', x, y, vx: 0, vy: 0, life: 22, maxLife: 22,
539:       size: size * 0.25, color, grav: 0, grow: size * 0.06,
540:     });
541:   }
542: 
543:   sparkArc(x, y, angle, color, heavy) {
544:     this.addParticle({
545:       type: 'slash', x, y, vx: 0, vy: 0, life: heavy ? 12 : 8, maxLife: heavy ? 12 : 8,
546:       size: heavy ? 58 : 34, color: '#ffffff', grav: 0, rot: angle,
547:     });
548:     this.addParticle({
549:       type: 'slash', x, y, vx: 0, vy: 0, life: heavy ? 14 : 9, maxLife: 14,
550:       size: heavy ? 44 : 26, color, grav: 0, rot: angle + 0.5,
551:     });
552:   }
553: 
554:   trailGhost(f) {
555:     this.addParticle({
556:       type: 'ghost', x: f.x, y: f.y, vx: 0, vy: 0, life: 14, maxLife: 14,
557:       size: 1, color: f.char.palette.glow, grav: 0,
558:       char: f.charId, facing: f.facing, slot: f.slot,
559:     });
560:   }
561: 
562:   chargeSpark(f) {
563:     const a = Math.random() * Math.PI * 2;
564:     const r = 26 + Math.random() * 26;
565:     this.addParticle({
566:       type: 'charge', x: f.x + Math.cos(a) * r, y: f.y - 48 + Math.sin(a) * r * 0.8,
567:       vx: -Math.cos(a) * 1.6, vy: -Math.sin(a) * 1.6, life: 14, maxLife: 14,
568:       size: 2 + Math.random() * 3, color: f.char.palette.glow, grav: 0, drag: 0.98,
569:     });
