572:   whiffSpark(x, y) {
573:     this.addParticle({
574:       type: 'ring', x, y, vx: 0, vy: 0, life: 12, maxLife: 12,
575:       size: 16, color: 'rgba(255,255,255,0.7)', grav: 0, grow: 2.4,
576:     });
577:   }
578: 
579:   popup(x, y, text, color, scale = 1) {
580:     this.popups.push({
581:       x, y, text, color, scale,
582:       life: 44, maxLife: 44, vy: 0,
583:     });
584:   }
585: 
586:   spawnProjectile(owner, spec) {
587:     const dir = owner.facing;
588:     const kind = spec.kind;
589:     this.projectiles.push({
590:       kind,
591:       owner: owner.slot,
592:       x: owner.x + (spec.ox || 30) * dir,
593:       y: owner.y + (spec.oy || -62),
594:       vx: (spec.speed || 9) * dir,
595:       vy: spec.vy || 0,
596:       gravity: spec.gravity || 0,
597:       r: spec.r || 11,
598:       damage: spec.damage,
599:       baseKB: spec.baseKB,
600:       growth: spec.growth,
601:       angle: spec.angle,
602:       life: spec.life || 110,
603:       maxLife: spec.life || 110,
604:       bounce: spec.bounce || 0,
605:       color: owner.char.palette.glow,
606:       rot: 0,
607:       dir,
608:     });
609:   }
610: 
611:   formatTime() {
612:     const secs = Math.floor(this.clock / 60);
613:     const m = Math.floor(secs / 60);
614:     const s = String(secs % 60).padStart(2, '0');
615:     return `${m}:${s}`;
616:   }
617: }
618: 
619: function circleRect(cx, cy, r, rect) {
620:   const nx = Math.max(rect.x, Math.min(cx, rect.x + rect.w));
621:   const ny = Math.max(rect.y, Math.min(cy, rect.y + rect.h));
622:   const dx = cx - nx;
623:   const dy = cy - ny;
624:   return dx * dx + dy * dy <= r * r;
625: }

