import { createRequire } from 'node:module';
import { mkdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(20000);

const errors = [];
const warnings = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR: ' + e.message); console.error('PAGEERROR:', e.message); });
page.on('console', (m) => {
  if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.error('CONSOLE ERROR:', m.text()); }
  if (m.type() === 'warning') warnings.push(m.text());
});
page.on('response', (r) => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const shot = async (name) => {
  const path = join(outDir, name + '.jpg');
  await page.screenshot({ path, type: 'jpeg', quality: 82 });
  console.log('shot:', path);
};

await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1500);
console.log('title screen:', await page.locator('#titleScreen').isVisible());
console.log('arena state:', await page.evaluate(() => ({ screen: window.__arena?.screen, fighters: window.__arena?.game.fighters.length })));
await shot('01-title');

// Quick play
await page.click('#quickPlay');
await page.waitForTimeout(2600);
console.log('battle:', await page.evaluate(() => ({ screen: window.__arena?.screen, phase: window.__arena?.game.phase, fighters: window.__arena?.game.fighters.map(f => ({ tag: f.tag, char: f.charId, kind: f.kind, x: Math.round(f.x), y: Math.round(f.y), stocks: f.stocks, damage: Math.round(f.damage) })), hudCards: document.querySelectorAll('.hud-card').length })));
await shot('02-battle');

// Attack for a moment
await page.keyboard.down('KeyD');
await page.keyboard.down('KeyF');
await page.waitForTimeout(300);
await page.keyboard.up('KeyF');
await page.keyboard.down('KeyF');
await page.waitForTimeout(500);
await page.keyboard.up('KeyF');
await page.keyboard.up('KeyD');
await page.waitForTimeout(400);
await shot('03-battle-action');

// Pause
await page.keyboard.press('Escape');
await page.waitForTimeout(350);
console.log('paused:', await page.evaluate(() => ({ paused: window.__arena?.paused, modalVisible: !document.querySelector('#pauseModal').classList.contains('hidden') })));
await shot('04-pause');
await page.click('#resumeBtn');
await page.waitForTimeout(300);
console.log('resumed:', await page.evaluate(() => window.__arena?.paused));

// Quit to title, then custom flow
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
await page.click('#quitBtn');
await page.waitForTimeout(600);
await page.click('#customPlay');
await page.waitForTimeout(1000);
console.log('select:', await page.evaluate(() => ({ screen: window.__arena?.screen, cards: document.querySelectorAll('.char-card').length, slots: window.__arena?.config.slots })));
await shot('05-select');

// Pick a fighter and toggle a slot
await page.click('.char-card[data-char="volt"]');
await page.waitForTimeout(500);
await page.click('#slotList [data-type="2"]');
await page.waitForTimeout(300);
await shot('06-select-edited');

await page.click('#toStage');
await page.waitForTimeout(900);
console.log('stage:', await page.evaluate(() => ({ screen: window.__arena?.screen, stage: window.__arena?.config.stage, cards: document.querySelectorAll('.stage-card').length })));
await shot('07-stage');

await page.click('.stage-card[data-stage="temple"]');
await page.waitForTimeout(500);
await shot('08-stage-selected');
await page.click('#startFight');
await page.waitForTimeout(2600);
console.log('temple battle:', await page.evaluate(() => ({ screen: window.__arena?.screen, stage: window.__arena?.game.stage.id, phase: window.__arena?.game.phase, slots: window.__arena?.game.fighters.map(f => `${f.tag}:${f.charId}:${f.kind}`) })));
await page.keyboard.down('KeyD');
await page.waitForTimeout(400);
await page.keyboard.press('KeyF');
await page.waitForTimeout(250);
await page.keyboard.up('KeyD');
await page.waitForTimeout(300);
await shot('09-temple-battle');

// Force a quick finish: zero the CPU stocks, then let the game detect it.
await page.evaluate(() => {
  const g = window.__arena.game;
  for (const f of g.fighters) if (f.kind === 'cpu') { f.stocks = 0; }
  g.checkEnd();
});
await page.waitForTimeout(2600);
console.log('results:', await page.evaluate(() => ({ screen: window.__arena?.screen, title: document.querySelector('#resultTitle')?.textContent, rows: document.querySelectorAll('.result-row').length, winner: document.querySelector('#winnerStrip')?.textContent.trim() })));
await shot('10-results');

await page.click('#rematch');
await page.waitForTimeout(2300);
console.log('rematch:', await page.evaluate(() => ({ screen: window.__arena?.screen, phase: window.__arena?.game.phase, fighters: window.__arena?.game.fighters.map(f => `${f.tag}:${f.stocks}`) })));
await shot('11-rematch');

// Mobile viewport smoke test on title
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
const mobileErrors = [];
mobile.on('pageerror', (e) => mobileErrors.push(e.message));
await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
await mobile.waitForTimeout(1600);
await mobile.screenshot({ path: join(outDir, '12-mobile-title.jpg'), type: 'jpeg', quality: 80 });
console.log('mobile errors:', mobileErrors.length ? mobileErrors : 'none');
console.log('mobile title visible:', await mobile.locator('#titleScreen').isVisible());

console.log('---');
console.log('ERRORS:', errors.length ? errors : 'none');
console.log('WARNINGS:', warnings.length ? warnings.slice(0, 8) : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

