import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
const out = await page.evaluate(() => new Promise((resolve) => {
  const a = window.__arena;
  const origTick = a.tick.bind(a);
  const origPoll = a.input.poll.bind(a.input);
  const origMenu = a.renderer.renderMenu.bind(a.renderer);
  const origFrame = a.frame.bind(a);
  const s = { ticks: [], polls: [], menus: [], frames: [], gaps: [], longtasks: 0 };
  a.input.poll = () => { const t = performance.now(); origPoll(); s.polls.push(performance.now() - t); };
  a.tick = () => { const t = performance.now(); origTick(); s.ticks.push(performance.now() - t); };
  a.renderer.renderMenu = (...args) => { const t = performance.now(); const r = origMenu(...args); s.menus.push(performance.now() - t); return r; };
  let last = performance.now();
  a.frame = (now) => { s.gaps.push(now - last); last = now; const t = performance.now(); origFrame(now); s.frames.push(performance.now() - t); };
  new PerformanceObserver((list) => { for (const e of list.getEntries()) if (e.duration > 50) s.longtasks++; }).observe({ entryTypes: ['longtask'] });
  setTimeout(() => {
    const stat = (x) => x.length ? { n: x.length, avg: +(x.reduce((p, c) => p + c, 0) / x.length).toFixed(2), max: +Math.max(...x).toFixed(2) } : null;
    resolve({ polls: stat(s.polls), ticks: stat(s.ticks), menus: stat(s.menus), frames: stat(s.frames), gaps: stat(s.gaps), longtasks: s.longtasks });
  }, 3000);
}));
console.log(out);
await browser.close();

