import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const base = config.browser.launchOptions;
const variants = {
  'headed-default': { headless: false, args: [] },
  'headed-noantialias': { headless: false, args: ['--disable-gpu', '--disable-gpu-compositing'] },
  'headless-default': { headless: true, args: [] },
  'headless-softwaregl': { headless: true, args: ['--disable-gpu'] },
  'headed-swiftshader-gl': { headless: false, args: ['--use-angle=swiftshader', '--use-gl=angle'] },
};
for (const [name, v] of Object.entries(variants)) {
  let browser;
  try {
    browser = await chromium.launch({ ...v, timeout: 30000 });
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
    await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 30000 });
    await page.waitForTimeout(1200);
    const title = await page.evaluate(() => new Promise((res) => { let n = 0; const t0 = performance.now(); const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f); else res(+(n / 1.5).toFixed(1)); }; requestAnimationFrame(f); }));
    await page.click('#quickPlay');
    await page.waitForTimeout(800);
    const battle = await page.evaluate(() => new Promise((res) => { let n = 0; const t0 = performance.now(); const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f); else res(+(n / 1.5).toFixed(1)); }; requestAnimationFrame(f); }));
    console.log(name, { title, battle });
  } catch (e) {
    console.log(name, 'ERROR', e.message.split('\n')[0]);
  } finally { await browser?.close(); }
}

