input.content:
import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch({ headless: true, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(20000);

const errors = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR: ' + e.message); console.error('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.error('CONSOLE ERROR:', m.text()); } });
page.on('response', (r) => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const shot = async (name) => {
  await page.screenshot({ path: join(outDir, name + '.jpg'), type: 'jpeg', quality: 84 });
  console.log('shot:', name);
};
const state = () => page.evaluate(() => {
  const a = window.__arena;
  return {
    screen: a.screen,
    paused: a.paused,
    phase: a.game.phase,
    slots: a.config.slots,
    fighters: a.game.fighters.map((f) => ({
      tag: f.tag, char: f.charId, kind: f.kind, slot: f.slot,
      x: Math.round(f.x), y: Math.round(f.y), stocks: f.stocks,
      damage: Math.round(f.damage), action: f.action, alive: f.alive,
    })),
    hudCards: document.querySelectorAll('.hud-card').length,
  };
});

await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1200);
console.log('title:', await page.locator('#titleScreen').isVisible(), await page.evaluate(() => window.__arena?.screen));
await shot('01-title');

// Main menu -> quick battle
await page.click('#quickPlay');
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
const beforeMove = await state();
await page.keyboard.down('KeyD');
await page.waitForTimeout(700);
await page.keyboard.up('KeyD');
await page.keyboard.press('KeyF');
await page.waitForTimeout(250);
const afterMove = await state();
console.log('movement:', { before: beforeMove.fighters[0].x, after: afterMove.fighters[0].x, p1Action: afterMove.fighters[0].action, hud: afterMove.hudCards });
await shot('02-battle');

// Pause / resume
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('pause:', await page.evaluate(() => ({ paused: window.__arena.paused, visible: !document.querySelector('#pauseModal').classList.contains('hidden') })));
await shot('03-pause');
await page.click('#resumeBtn');
await page.waitForTimeout(200);

// KO + respawn check
await page.evaluate(() => { window.__arena.game.fighters[0].x = 2400; window.__arena.game.fighters[0].y = 0; });
await page.waitForTimeout(1400);
const ko = await state();
await page.waitForTimeout(2600);
const respawn = await state();
console.log('ko/respawn:', {
  afterKO: ko.fighters[0],
  afterRespawn: respawn.fighters[0],
  hudStocksLost: await page.evaluate(() => document.querySelectorAll('.hud-card .stock-pip.lost').length),
});
await shot('04-respawn');

// Quit to title, enter custom 4-player setup
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
await page.click('#quitBtn');
await page.waitForTimeout(500);
await page.click('#customPlay');
await page.waitForTimeout(800);
console.log('select:', await state());
await shot('05-select');

// Fill slots 3 and 4 with CPUs
for (const i of [2, 3]) {
  await page.click(`#slotList [data-type="${i}"]`);
  await page.waitForTimeout(120);
  await page.click(`#slotList [data-type="${i}"]`);
  await page.waitForTimeout(120);
}
await page.click('.char-card[data-char="glacier"]');
await page.waitForTimeout(350);
console.log('lineup:', (await state()).slots);
await shot('06-select-four');

await page.click('#toStage');
await page.waitForTimeout(700);
await shot('07-stage');
await page.click('.stage-card[data-stage="ember"]');
await page.waitForTimeout(450);
await shot('08-stage-selected');
await page.click('#startFight');
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
await page.waitForTimeout(200);
const four = await state();
console.log('four-player battle:', { stage: await page.evaluate(() => window.__arena.game.stage.id), fighters: four.fighters, hud: four.hudCards });
await page.keyboard.down('KeyD');
await page.waitForTimeout(500);
await page.keyboard.up('KeyD');
await page.waitForTimeout(350);
await shot('09-four-player');

// Force match end by eliminating every CPU
await page.evaluate(() => {
  const g = window.__arena.game;
  for (const f of g.fighters) if (f.kind === 'cpu') f.stocks = 0;
  g.checkEnd();
});
await page.waitForFunction(() => window.__arena.screen === 'results', null, { timeout: 12000 });
await page.waitForTimeout(400);
console.log('results:', await page.evaluate(() => ({
  title: document.querySelector('#resultTitle')?.textContent,
  eyebrow: document.querySelector('#resultEyebrow')?.textContent,
  rows: document.querySelectorAll('.result-row').length,
  winner: document.querySelector('#winnerStrip')?.textContent.trim(),
})));
await shot('10-results');

// Rematch and verify a fresh battle starts
await page.click('#rematch');
await page.waitForFunction(() => window.__arena.screen === 'battle' && window.__arena.game.phase === 'fight', null, { timeout: 12000 });
console.log('rematch:', await state());
await shot('11-rematch');

// Mobile layout smoke test
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
const mobileErrors = [];
mobile.on('pageerror', (e) => mobileErrors.push(e.message));
await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
await mobile.waitForTimeout(1200);
await mobile.screenshot({ path: join(outDir, '12-mobile-title.jpg'), type: 'jpeg', quality: 82 });
await mobile.click('#customPlay');
await mobile.waitForTimeout(900);
await mobile.screenshot({ path: join(outDir, '13-mobile-select.jpg'), type: 'jpeg', quality: 82 });
console.log('mobile:', { titleOk: await mobile.locator('#titleScreen').isVisible(), errors: mobileErrors.length ? mobileErrors : 'none' });

console.log('---');
console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#customPlay');
await page.waitForTimeout(900);
console.log(await page.evaluate(() => {
  const r = (sel) => { const e = document.querySelector(sel); const b = e.getBoundingClientRect(); const s = getComputedStyle(e); return { rect: { x: b.x, y: b.y, w: b.width, h: b.height }, display: s.display, position: s.position, height: s.height, minHeight: s.minHeight, overflow: s.overflow, gridTemplateRows: s.gridTemplateRows, order: s.order }; };
  return {
    screen: r('#selectScreen'),
    topbar: r('#selectScreen .top-bar'),
    main: r('.select-main'),
    charGrid: r('.char-grid'),
    lineup: r('.lineup-panel'),
    slotList: r('.slot-list'),
    toStage: r('#toStage'),
    scroll: { top: document.querySelector('.select-main').scrollTop, height: document.querySelector('.select-main').scrollHeight, client: document.querySelector('.select-main').clientHeight },
  };
}));
await browser.close();

