import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
mkdirSync(outDir, { recursive: true });
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.error('CONSOLE:', m.text()); } });
const shot = async (n) => { await page.screenshot({ path: join(outDir, n + '.jpg'), type: 'jpeg', quality: 84 }); console.log('shot:', n); };
const info = () => page.evaluate(() => {
  const a = window.__arena;
  return {
    screen: a.screen,
    phase: a.game.phase,
    paused: a.paused,
    fighters: a.game.fighters.map((f) => ({ tag: f.tag, slot: f.slot, kind: f.kind, char: f.charId, x: Math.round(f.x), y: Math.round(f.y), stocks: f.stocks, ko: f.koTimer, eliminated: f.eliminated, damage: Math.round(f.damage), action: f.action })),
    resultTitle: document.querySelector('#resultTitle')?.textContent,
    resultRows: document.querySelectorAll('.result-row').length,
    winner: document.querySelector('#winnerStrip')?.textContent.trim(),
  };
});
const waitFight = () => page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(1100);
await shot('01-title');

// Real match flow: player self-destruct + three CPU eliminations
await page.click('#quickPlay');
await waitFight();
const p0 = await info();
const x0 = p0.fighters[0].x;
await page.keyboard.down('KeyD');
await page.waitForTimeout(600);
await page.keyboard.up('KeyD');
await page.keyboard.press('KeyF');
await page.waitForTimeout(200);
const p1 = await info();
console.log('MOVED?', x0, '->', p1.fighters[0].x, 'action:', p1.fighters[0].action);
await shot('02-battle');

await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('PAUSE:', await page.evaluate(() => ({ paused: window.__arena.paused, modal: !document.querySelector('#pauseModal').classList.contains('hidden') })));
await shot('03-pause');
await page.click('#resumeBtn');
await page.waitForTimeout(200);

// Self-destruct P1 once, confirm stock loss + respawn
await page.evaluate(() => { const f = window.__arena.game.fighters[0]; f.x = 2400; f.y = 0; });
await page.waitForTimeout(1500);
let s = await info();
console.log('P1 KO:', s.fighters[0].stocks, 'stocks, koTimer', s.fighters[0].ko);
await page.waitForTimeout(3000);
s = await info();
console.log('P1 RESPAWN:', s.fighters[0].stocks, 'stocks, koTimer', s.fighters[0].ko, 'y', s.fighters[0].y, 'eliminated', s.fighters[0].eliminated);

// Eliminate CPU three times through real blast-zone KOs
for (let i = 0; i < 3; i++) {
  await page.evaluate(() => {
    const g = window.__arena.game;
    const f = g.fighters.find((x) => x.kind === 'cpu' && !x.eliminated);
    if (f) { f.x = 2400; f.y = 0; f.lastHitBy = 0; }
  });
  await page.waitForTimeout(1500);
  s = await info();
  console.log(`CPU KO ${i + 1}:`, s.fighters[1]?.stocks, 'stocks, koTimer', s.fighters[1]?.ko, 'phase', s.phase);
  if (i < 2) await page.waitForTimeout(2400);
}
await page.waitForFunction(() => window.__arena.screen === 'results', null, { timeout: 12000 });
await page.waitForTimeout(500);
const res = await info();
console.log('RESULTS:', { title: res.resultTitle, rows: res.resultRows, winner: res.winner, phase: res.phase });
console.log('RESULT STATS:', await page.evaluate(() => Array.from(document.querySelectorAll('.result-row')).map((r) => r.textContent.replace(/\s+/g, ' ').trim())));
await shot('10-results');

// Custom flow with a second human player + ember stage
await page.click('#resultsCustom');
await page.waitForTimeout(800);
// Slot 1: CPU -> OFF -> HUMAN
await page.click('#slotList [data-type="1"]');
await page.waitForTimeout(120);
await page.click('#slotList [data-type="1"]');
await page.waitForTimeout(350);
console.log('LINEUP:', (await info()));
await shot('05-select-two-human');
await page.click('#toStage');
await page.waitForTimeout(600);
await page.click('.stage-card[data-stage="ember"]');
await page.waitForTimeout(400);
await shot('08-stage-selected');
await page.click('#startFight');
await waitFight();
const p2before = await info();
await page.keyboard.down('ArrowRight');
await page.waitForTimeout(500);
await page.keyboard.up('ArrowRight');
await page.keyboard.press('Comma');
await page.waitForTimeout(200);
const p2after = await info();
console.log('P2 INPUT:', p2before.fighters[1].x, '->', p2after.fighters[1].x, 'action', p2after.fighters[1].action, 'kinds', p2after.fighters.map((f) => f.kind));
await shot('09-two-human-ember');

// 4-player visual
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
await page.click('#quitBtn');
await page.waitForTimeout(400);
await page.click('#customPlay');
await page.waitForTimeout(700);
for (const i of [2, 3]) { await page.click(`#slotList [data-type="${i}"]`); await page.waitForTimeout(100); await page.click(`#slotList [data-type="${i}"]`); await page.waitForTimeout(100); }
await page.click('#toStage');
await page.waitForTimeout(500);
await page.click('.stage-card[data-stage="frost"]');
await page.waitForTimeout(300);
await page.click('#startFight');
await waitFight();
await page.waitForTimeout(300);
await shot('11-four-player-frost');
console.log('FOUR:', (await info()).fighters.map((f) => f.tag + ':' + f.char + ':' + f.kind));

// Mobile layout
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
await mobile.waitForTimeout(1000);
const mobileTitle = await mobile.locator('#titleScreen').isVisible();
await mobile.screenshot({ path: join(outDir, '12-mobile-title.jpg'), type: 'jpeg', quality: 82 });
await mobile.click('#customPlay');
await mobile.waitForTimeout(900);
const mobileScroll = await mobile.evaluate(() => {
  const m = document.querySelector('.select-main');
  const panel = document.querySelector('.lineup-panel').getBoundingClientRect();
  const grid = document.querySelector('.char-grid').getBoundingClientRect();
  return { overlap: panel.bottom > grid.top + 1, scrollHeight: m.scrollHeight, clientHeight: m.clientHeight, panelH: Math.round(panel.height), gridTop: Math.round(grid.top), panelBottom: Math.round(panel.bottom) };
});
await mobile.screenshot({ path: join(outDir, '13-mobile-select.jpg'), type: 'jpeg', quality: 82 });
console.log('MOBILE:', { title: mobileTitle, scroll: mobileScroll });

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

