import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.error('CONSOLE:', m.text()); } });
const shot = async (n) => { await page.screenshot({ path: join(outDir, n + '.jpg'), type: 'jpeg', quality: 84 }); console.log('shot:', n); };

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#howToPlay');
await page.waitForTimeout(350);
console.log('HOWTO:', await page.evaluate(() => ({ visible: !document.querySelector('#howToModal').classList.contains('hidden'), title: document.querySelector('#howToTitle').textContent })));
await shot('14-howto');
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
console.log('HOWTO CLOSED:', await page.evaluate(() => document.querySelector('#howToModal').classList.contains('hidden')));

await page.click('#customPlay');
await page.waitForTimeout(600);
await page.click('#cpuLevelPicker [data-level="3"]');
await page.waitForTimeout(200);
console.log('CPU LEVEL:', await page.evaluate(() => window.__arena.config.difficulty));
await page.click('#toStage');
await page.waitForTimeout(500);
await page.click('#stockPicker [data-stocks="1"]');
await page.waitForTimeout(250);
const stockInfo = await page.evaluate(() => ({ stocks: window.__arena.config.stocks, blurb: document.querySelector('#stageBlurb').textContent.replace(/\s+/g, ' ').trim() }));
console.log('STOCKS:', stockInfo);
await shot('15-stage-one-stock');

await page.click('#startFight');
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
await page.waitForTimeout(200);
console.log('ONE STOCK BATTLE:', await page.evaluate(() => ({ stocks: window.__arena.config.stocks, pips: document.querySelectorAll('.hud-card .stock-pip').length })));
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
await page.click('#pauseControlsBtn');
await page.waitForTimeout(300);
console.log('PAUSE CONTROLS:', await page.evaluate(() => ({ pause: !document.querySelector('#pauseModal').classList.contains('hidden'), howto: !document.querySelector('#howToModal').classList.contains('hidden') })));
await shot('16-pause-controls');
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
console.log('BACK TO PAUSE:', await page.evaluate(() => ({ pause: !document.querySelector('#pauseModal').classList.contains('hidden'), howto: document.querySelector('#howToModal').classList.contains('hidden') })));
await page.click('#restartBtn');
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
console.log('RESTART:', await page.evaluate(() => ({ paused: window.__arena.paused, stocks: window.__arena.game.fighters.map((f) => f.stocks), phase: window.__arena.game.phase })));

// Sound toggle
const soundBefore = await page.evaluate(() => document.querySelector('#soundBtn').textContent.trim());
await page.click('#soundBtn');
await page.waitForTimeout(200);
const soundAfter = await page.evaluate(() => ({ text: document.querySelector('#soundBtn').textContent.trim(), stored: localStorage.getItem('smash-arena-sound') }));
await page.click('#soundBtn');
console.log('SOUND:', { soundBefore, soundAfter });

// Width checks for header/system button collisions
for (const width of [1024, 820]) {
  await page.setViewportSize({ width, height: 800 });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(800);
  await shot(`17-title-${width}`);
  await page.click('#customPlay');
  await page.waitForTimeout(700);
  const overlap = await page.evaluate(() => {
    const a = document.querySelector('#selectScreen .top-bar').getBoundingClientRect();
    const b = document.querySelector('.system-buttons').getBoundingClientRect();
    return { topBarRight: Math.round(a.right), sysLeft: Math.round(b.left), overlap: a.right > b.left };
  });
  console.log('WIDTH', width, overlap);
  await shot(`18-select-${width}`);
}

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();

