import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(700);
const out = await page.evaluate(() => {
  const a = window.__arena;
  a.startBattle({
    stocks: 1,
    difficulty: 3,
    stage: 'ember',
    slots: [
      { type: 'human', char: 'blaze' },
      { type: 'cpu', char: 'volt' },
      { type: 'cpu', char: 'glacier' },
      { type: 'cpu', char: 'sprout' },
    ],
  });
  a.paused = true; // stop the normal loop from advancing the sim; drive it manually
  const g = a.game;
  let frames = 0;
  let maxProjectiles = 0;
  let maxParticles = 0;
  while (g.phase !== 'ended' && frames < 60 * 240) {
    g.update([]);
    frames++;
    maxProjectiles = Math.max(maxProjectiles, g.projectiles.length);
    maxParticles = Math.max(maxParticles, g.particles.length);
    if (!Number.isFinite(g.camera.x) || !Number.isFinite(g.camera.y)) throw new Error('camera NaN at ' + frames);
    for (const f of g.fighters) {
      if (!Number.isFinite(f.x) || !Number.isFinite(f.y) || !Number.isFinite(f.damage)) throw new Error('fighter NaN at ' + frames + ' ' + f.tag);
      if (f.damage < 0 || f.damage > 999) throw new Error('damage out of range ' + f.damage);
    }
  }
  return {
    frames,
    phase: g.phase,
    results: g.results ? {
      rows: g.results.rows.map((r) => ({ tag: r.tag, kind: r.kind, placement: r.placement, stocks: r.stocks, kos: r.kos, falls: r.falls, dealt: r.dealt })),
      winner: g.results.winner ? { tag: g.results.winner.tag, charName: g.results.winner.charName } : null,
    } : null,
    maxProjectiles,
    maxParticles,
    screen: a.screen,
    resultTitle: document.querySelector('#resultTitle')?.textContent,
    uiRows: document.querySelectorAll('.result-row').length,
  };
});
console.log(JSON.stringify(out, null, 2));
console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();

