import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => console.error('PAGEERROR', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(700);
for (const char of ['blaze', 'volt', 'glacier', 'sprout']) {
  await page.evaluate((char) => {
    window.__arena.startBattle({
      stocks: 3, difficulty: 2, stage: 'sky',
      slots: [{ type: 'human', char }, { type: 'cpu', char: 'sprout' }, { type: 'off', char: 'volt' }, { type: 'off', char: 'glacier' }],
    });
    window.__arena.game.ais = [];
  }, char);
  await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
  await page.waitForTimeout(100);
  // neutral special -> projectile
  await page.keyboard.press('KeyG');
  await page.waitForTimeout(350);
  const proj = await page.evaluate(() => ({
    char: window.__arena.game.fighters[0].charId,
    action: window.__arena.game.fighters[0].action,
    move: window.__arena.game.fighters[0].move?.key,
    projectiles: window.__arena.game.projectiles.map((p) => p.kind),
  }));
  // shield
  await page.keyboard.down('KeyH');
  await page.waitForTimeout(160);
  const shield = await page.evaluate(() => ({ action: window.__arena.game.fighters[0].action, shield: Math.round(window.__arena.game.fighters[0].shieldHP) }));
