        if (this.down.has(`${slot}:${action}`)) held.add(action);
      }
      for (const action of this.pending[slot]) {
        pressed.add(action);
        held.add(action);
      }
    }

    const pad = this.pads.find((p) => p.index === slot);
    if (pad) {
      const ax = pad.axes[0] || 0;
      const ay = pad.axes[1] || 0;
