197:         return;
198:       }
199:       if (prev || next) {
200:         const i = Number((prev || next).dataset.prev || (prev || next).dataset.next);
201:         const slot = this.config.slots[i];
202:         const idx = CHARACTERS.findIndex((c) => c.id === slot.char);
203:         const delta = next ? 1 : -1;
204:         slot.char = CHARACTERS[(idx + delta + CHARACTERS.length) % CHARACTERS.length].id;
205:         if (slot.type === 'off') slot.type = i === 0 ? 'human' : 'cpu';
206:         this.activeSlot = i;
207:         audio.hover();
208:         this.renderSelect();
209:         return;
