513:   buildHud() {
514:     const hud = this.els.hud;
515:     const fighters = this.game.fighters;
516:     const cards = fighters.map((f) => `
517:       <div class="hud-card" data-slot="${f.slot}" style="--accent:${f.color}">
518:         <div class="hud-portrait"><img src="${this.avatarURL(f.charId)}" alt="" /></div>
519:         <div class="hud-ident">
520:           <div class="hud-player">${f.tag} <span class="tag">${f.kind === 'cpu' ? `CPU ${DIFFICULTIES.find((d) => d.id === f.difficulty)?.label || ''}` : 'YOU'}</span></div>
521:           <div class="hud-name">${f.char.name}</div>
522:           <div class="hud-stocks">${'<span class="stock-pip"></span>'.repeat(this.config.stocks)}</div>
523:         </div>
524:         <div class="hud-dmg">0<small>%</small></div>
525:         <div class="hud-shield"><i></i></div>
526:       </div>`).join('');
527:     hud.innerHTML = `
528:       <div class="hud-topline"><span class="dot"></span>${this.game.stage.name} <span class="dot"></span> STOCK <span class="dot"></span> <span class="time">0:00</span></div>
529:       <div class="hud-cards">${cards}</div>
530:       <div class="hud-tagline"><span>ESC PAUSE</span><span>${fighters.length} FIGHTERS</span></div>`;
531:     this.cards.clear();
532:     for (const f of fighters) {
533:       const root = hud.querySelector(`.hud-card[data-slot="${f.slot}"]`);
534:       this.cards.set(f.slot, {
535:         root,
536:         dmg: root.querySelector('.hud-dmg'),
537:         stocks: Array.from(root.querySelectorAll('.stock-pip')),
538:         shield: root.querySelector('.hud-shield i'),
539:         time: hud.querySelector('.time'),
540:         lastStocks: f.stocks,
541:         lastDamage: -1,
542:       });
543:     }
544:     this.lastHud = hud.querySelector('.time');
545:   }
