547:   updateHud() {
548:     if (!this.cards.size) return;
549:     for (const f of this.game.fighters) {
550:       const c = this.cards.get(f.slot);
551:       if (!c) continue;
552:       const rounded = Math.round(f.damage);
553:       if (rounded !== c.lastDamage) {
554:         c.dmg.innerHTML = `${rounded}<small>%</small>`;
555:         c.root.classList.toggle('low', rounded >= 50 && rounded < 100);
556:         c.root.classList.toggle('mid', rounded >= 100 && rounded < 150);
557:         c.root.classList.toggle('high', rounded >= 150);
558:         c.root.classList.toggle('danger', rounded >= 200);
559:         c.lastDamage = rounded;
560:       }
561:       if (f.stocks !== c.lastStocks) {
562:         c.stocks.forEach((pip, i) => pip.classList.toggle('lost', i >= f.stocks));
563:         c.root.classList.toggle('koed', f.stocks <= 0);
564:         c.lastStocks = f.stocks;
565:       }
566:       c.root.classList.toggle('shielding', f.action === 'shield');
567:       c.shield.style.transform = `scaleX(${Math.max(0, f.shieldHP) / 100})`;
568:       c.root.classList.toggle('koed', f.stocks <= 0 || f.eliminated);
569:     }
570:     if (this.lastHud) this.lastHud.textContent = this.game.formatTime();
571:   }
