574:   showResults(results) {
575:     const winner = results.winner;
576:     const anyHuman = results.rows.some((r) => r.kind === 'human');
577:     let title = 'DRAW';
578:     if (winner) title = winner.kind === 'human' ? 'VICTORY' : anyHuman ? 'DEFEAT' : 'CPU WINS';
579:     this.els.resultTitle.textContent = title;
580:     this.els.resultEyebrow.textContent = `MATCH COMPLETE · ${Math.floor(results.duration / 60 / 60)}:${String(Math.floor(results.duration / 60) % 60).padStart(2, '0')} · ${results.stage.name}`;
581:     this.els.resultTable.innerHTML = results.rows.map((r) => `
582:       <div class="result-row ${r.placement === 1 ? 'winner' : ''}" style="--accent:${r.color}">
583:         <div class="place">${r.placement}</div>
584:         <div class="ra-avatar"><canvas data-result-avatar="${r.charId}"></canvas></div>
585:         <div class="ra-name">${r.charName}<small>${r.tag} · ${r.kind === 'cpu' ? 'CPU' : 'PLAYER'}</small></div>
586:         <div class="stat">${r.kos}<small>KOs</small></div>
587:         <div class="stat">${r.falls}<small>FALLS</small></div>
588:         <div class="stat">${Math.round(r.dealt)}<small>DAMAGE</small></div>
589:       </div>`).join('');
590:     const winChar = winner ? CHAR_MAP[winner.charId] : null;
591:     this.els.winnerStrip.innerHTML = winner
592:       ? `<div class="win-avatar"><canvas data-winner-avatar="${winner.charId}"></canvas></div><span>${winner.tag} · ${winner.charName} TAKES THE ARENA</span>`
593:       : '<span>NO CONTEST · EVERYONE BLASTED OUT</span>';
594:     requestAnimationFrame(() => {
595:       $$('canvas[data-result-avatar]').forEach((cv) => drawAvatar(cv, cv.dataset.resultAvatar));
596:       const wc = document.querySelector('canvas[data-winner-avatar]');
597:       if (wc) drawAvatar(wc, wc.dataset.winnerAvatar);
598:     });
599:     this.paused = true;
600:     this.els.hud.classList.remove('active');
601:     this.showScreen('results');
602:     this.els.hud.classList.remove('active');
603:     if (winChar && winner.kind === 'human') audio.win();
604:   }
