607:   setPaused(paused) {
608:     if (this.screen !== 'battle') return;
609:     if (paused === this.paused) return;
610:     this.paused = paused;
611:     this.els.pause.classList.toggle('hidden', !paused);
612:     if (paused) {
613:       this.input.releaseAll();
614:       this.els.howto.classList.add('hidden');
615:     } else {
616:       this.input.releaseAll();
617:       this.els.howto.classList.add('hidden');
618:     }
619:   }
