631:   // -------------------------------------------------------------------------
632:   tick() {
633:     this.input.poll();
634:     if (this.screen === 'battle') {
635:       if (this.input.pausePressed()) {
636:         this.setPaused(!this.paused);
637:         return;
638:       }
639:       if (this.paused) return;
640:       const inputs = [];
641:       for (const f of this.game.fighters) {
642:         if (f.kind === 'human') inputs[f.slot] = this.input.stateFor(f.slot);
643:       }
644:       this.game.update(inputs);
645:       this.updateHud();
646:       if (this.game.phase === 'ended') {
647:         // results are delivered by the game callback
648:       }
649:     }
650:   }
651: 
652:   frame(now) {
653:     const delta = Math.min(100, now - this.lastFrame);
654:     this.lastFrame = now;
655:     this.acc += delta;
656:     const step = 1000 / 60;
657:     let iterations = 0;
658:     while (this.acc >= step && iterations < 5) {
659:       this.tick();
660:       this.acc -= step;
661:       iterations++;
662:     }
663:     if (this.acc > step * 5) this.acc = 0;
664: 
665:     if (this.screen === 'battle' || this.screen === 'results') {
666:       this.renderer.renderGame(this.game, now);
667:     } else {
668:       this.renderer.renderMenu(this.config.stage, now, this.screen === 'title' ? 'title' : 'menu');
669:     }
670:     requestAnimationFrame((t) => this.frame(t));
671:   }
672: }
