```
bindTouchControls() {
  const pad = this.els.touchDpad;
  const actions = this.els.touchControls;
  if (!pad || !actions) return;

  let dpadPointer = null;
  const paintDirs = (dirs) => {
    for (const btn of pad.querySelectorAll('[data-touch]')) {
      btn.classList.toggle('pressed', dirs.has(btn.dataset.touch));
    }
    for (const dir of ['left','right','up','down']) {
      if (dirs.has(dir) && !this.touchDirs.has(dir)) this.input.touchDown(dir);
      if (!dirs.has(dir) && this.touchDirs.has(dir)) this.input.touchUp(dir);
    }
    this.touchDirs = dirs;
  };
  const dirsFrom = (e) => {
    const r = pad.getBoundingClientRect();
    const nx = (e.clientX - (r.left + r.width/2)) / (r.width/2);
    const ny = (e.clientY - (r.top + r.height/2)) / (r.height/2);
    const dead = 0.24;
    const dirs = new Set();
    if (nx < -dead) dirs.add('left');
    if (nx > dead) dirs.add('right');
    if (ny < -dead) dirs.add('up');
    if (ny > dead) dirs.add('down');
    return dirs;
  };
  pad.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    if (dpadPointer !== null) return;
    dpadPointer = e.pointerId;
    pad.setPointerCapture?.(e.pointerId);
    audio.init();
    paintDirs(dirsFrom(e));
  });
  pad.addEventListener('pointermove', (e) => {
    if (e.pointerId !== dpadPointer) return;
    e.preventDefault();
    paintDirs(dirsFrom(e));
  });
  const endDpad = (e) => {
    if (dpadPointer === null || (e.pointerId != null && e.pointerId !== dpadPointer)) return;
    dpadPointer = null;
    paintDirs(new Set());
  };
  pad.addEventListener('pointerup', endDpad);
  pad.addEventListener('pointercancel', endDpad);
  pad.addEventListener('lostpointercapture', endDpad);

  actions.addEventListener('pointerdown', (e) => {
    const btn = e.target.closest('[data-touch]');
    if (!btn) return;
    e.preventDefault();
    audio.init();
    btn.setPointerCapture?.(e.pointerId);
    btn.classList.add('pressed');
    const action = btn.dataset.touch;
    this.touchActions.add(action);
    this.input.touchDown(action);
  });
  const endAction = (e) => {
    const btn = e.target.closest?.('[data-touch]');
    if (!btn) return;
    btn.classList.remove('pressed');
    const action = btn.dataset.touch;
    this.touchActions.delete(action);
    this.input.touchUp(action);
  };
  actions.addEventListener('pointerup', endAction);
  actions.addEventListener('pointercancel', endAction);
  actions.addEventListener('lostpointercapture', endAction);
  actions.addEventListener('contextmenu', (e) => e.preventDefault());
}
```

