import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
mkdirSync(outDir, { recursive: true });
const browser = await chromium.launch({ headless: true });

const errors = [];
const watch = (page, label) => {
  page.on('pageerror', (e) => { errors.push(`${label} PAGEERROR ${e.message}`); console.error(label, 'PAGEERROR', e.message); });
  page.on('console', (m) => { if (m.type() === 'error') { errors.push(`${label} CONSOLE ${m.text()}`); console.error(label, 'CONSOLE', m.text()); } });
};

// --- Desktop: touch controls should stay hidden by default ---
const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
watch(desktop, 'desktop');
await desktop.goto('http://localhost:3000/', { waitUntil: 'load' });
await desktop.waitForTimeout(700);
await desktop.click('#quickPlay');
await desktop.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
console.log('desktop touch state:', await desktop.evaluate(() => ({
  visible: !document.querySelector('#touchControls').classList.contains('hidden'),
  pauseVisible: !document.querySelector('#battlePauseBtn').classList.contains('hidden'),
  touchMode: document.getElementById('app').classList.contains('touch-mode'),
  slot: window.__arena.input.touchSlot,
})));
await desktop.click('#battlePauseBtn');
await desktop.waitForTimeout(250);
console.log('desktop pause btn opens modal:', await desktop.evaluate(() => !document.querySelector('#pauseModal').classList.contains('hidden')));
await desktop.screenshot({ path: join(outDir, '11-pause-touch-toggle.jpg'), type: 'jpeg', quality: 84 });

// --- Mobile with touch: controls appear and work ---
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
watch(mobile, 'mobile');
await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
await mobile.waitForTimeout(800);
console.log('mobile auto-detect:', await mobile.evaluate(() => ({
  coarse: matchMedia('(pointer: coarse)').matches,
  maxTouch: navigator.maxTouchPoints,
  enabled: window.__arena.touchEnabled,
  pressHint: getComputedStyle(document.querySelector('.press-hint')).display,
})));
await mobile.click('#quickPlay');
await mobile.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
await mobile.evaluate(() => { window.__arena.game.ais = []; });
await mobile.waitForTimeout(400);
const geom = await mobile.evaluate(() => {
  const rect = (sel) => { const b = document.querySelector(sel).getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), right: Math.round(b.right), bottom: Math.round(b.bottom) }; };
  return {
    visible: !document.querySelector('#touchControls').classList.contains('hidden'),
    aria: document.querySelector('#touchControls').getAttribute('aria-hidden'),
    dpad: rect('.touch-dpad'),
    actions: rect('.touch-actions'),
    viewport: { w: innerWidth, h: innerHeight },
    overlap: document.querySelector('.touch-dpad').getBoundingClientRect().right > document.querySelector('.touch-actions').getBoundingClientRect().left,
    slot: window.__arena.input.touchSlot,
  };
});
console.log('mobile touch layout:', geom);
await mobile.screenshot({ path: join(outDir, '12-mobile-touch-battle.jpg'), type: 'jpeg', quality: 82 });

// Hold right on the d-pad
const dpad = geom.dpad;
const centerX = dpad.x + dpad.w / 2;
const centerY = dpad.y + dpad.h / 2;
const startX = await mobile.evaluate(() => Math.round(window.__arena.game.fighters[0].x));
await mobile.mouse.move(centerX + dpad.w * 0.38, centerY);
await mobile.mouse.down();
await mobile.waitForTimeout(420);
const moveState = await mobile.evaluate(() => ({
  action: window.__arena.game.fighters[0].action,
  dirs: [...window.__arena.touchDirs],
  pressedButtons: Array.from(document.querySelectorAll('.touch-dir.pressed')).map((b) => b.dataset.touch),
}));
await mobile.mouse.up();
await mobile.waitForTimeout(150);
const endX = await mobile.evaluate(() => Math.round(window.__arena.game.fighters[0].x));
console.log('mobile dpad right:', { startX, endX, moved: endX - startX, ...moveState });
console.log('mobile dpad release clean:', await mobile.evaluate(() => ({ dirs: window.__arena.touchDirs.size, held: [...window.__arena.input.touchHeld] })));

// Tap jump via the on-screen button
const jump = await mobile.evaluate(() => { const b = document.querySelector('.act-jump').getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; });
await mobile.touchscreen.tap(jump.x, jump.y);
await mobile.waitForTimeout(120);
console.log('mobile jump tap:', await mobile.evaluate(() => ({ grounded: window.__arena.game.fighters[0].grounded, vy: Math.round(window.__arena.game.fighters[0].vy) })));

// Hold shield
const shield = await mobile.evaluate(() => { const b = document.querySelector('.act-shield').getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; });
await mobile.mouse.move(shield.x, shield.y);
await mobile.mouse.down();
await mobile.waitForTimeout(220);
console.log('mobile shield hold:', await mobile.evaluate(() => ({ action: window.__arena.game.fighters[0].action, shieldHP: Math.round(window.__arena.game.fighters[0].shieldHP) })));
await mobile.mouse.up();
await mobile.waitForTimeout(250);

// Attack tap
const attack = await mobile.evaluate(() => { const b = document.querySelector('.act-attack').getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; });
await mobile.touchscreen.tap(attack.x, attack.y);
await mobile.waitForTimeout(80);
console.log('mobile attack tap:', await mobile.evaluate(() => ({ action: window.__arena.game.fighters[0].action, move: window.__arena.game.fighters[0].moveKey })));
await mobile.waitForTimeout(500);

// In-game pause button
console.log('mobile pause btn visible:', await mobile.evaluate(() => !document.querySelector('#battlePauseBtn').classList.contains('hidden')));
await mobile.click('#battlePauseBtn');
await mobile.waitForTimeout(300);
console.log('mobile paused:', await mobile.evaluate(() => ({
  pause: !document.querySelector('#pauseModal').classList.contains('hidden'),
  touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
  toggle: document.querySelector('#touchToggleBtn').textContent.replace(/\s+/g, ' ').trim(),
})));
await mobile.screenshot({ path: join(outDir, '13-mobile-pause.jpg'), type: 'jpeg', quality: 82 });

// Toggle off, resume, confirm hidden, then toggle back on via pause
await mobile.click('#touchToggleBtn');
await mobile.waitForTimeout(200);
console.log('after toggle off:', await mobile.evaluate(() => ({ enabled: window.__arena.touchEnabled, label: document.querySelector('#touchToggleBtn').textContent.replace(/\s+/g, ' ').trim(), stored: localStorage.getItem('smash-arena-touch') })));
await mobile.click('#resumeBtn');
await mobile.waitForTimeout(300);
console.log('resumed without touch:', await mobile.evaluate(() => ({
  touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
  pauseVisible: !document.querySelector('#battlePauseBtn').classList.contains('hidden'),
})));
await mobile.click('#battlePauseBtn');
await mobile.waitForTimeout(250);
await mobile.click('#touchToggleBtn');
await mobile.waitForTimeout(200);
await mobile.click('#resumeBtn');
await mobile.waitForTimeout(300);
console.log('resumed with touch:', await mobile.evaluate(() => ({
  touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
  enabled: window.__arena.touchEnabled,
})));

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

