  p.on('pageerror', (e) => { errors.push(`${tag} ${e.message}`); console.error(tag, 'PAGEERROR', e.message); });
  p.on('console', (m) => { if (m.type() === 'error') { errors.push(`${tag} ${m.text()}`); console.error(tag, 'CONSOLE', m.text()); } });
};

// Mobile flow
