import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.error('CONSOLE', m.text()); } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(700);

// Four fighters, three stocks, touch enabled
await page.evaluate(() => {
  window.__arena.startBattle({
    stocks: 3, difficulty: 2, stage: 'ember',
    slots: [
      { type: 'human', char: 'blaze' },
      { type: 'cpu', char: 'volt' },
      { type: 'cpu', char: 'glacier' },
      { type: 'cpu', char: 'sprout' },
    ],
  });
});
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
await page.waitForTimeout(500);
const pos = async (sel) => page.evaluate((sel) => { const b = document.querySelector(sel).getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; }, sel);
const dpad = await page.evaluate(() => { const b = document.querySelector('.touch-dpad').getBoundingClientRect(); return { x: b.x, y: b.y, w: b.width, h: b.height }; });
const jump = await pos('.act-jump');
const attack = await pos('.act-attack');
const special = await pos('.act-special');
const shield = await pos('.act-shield');
const dodge = await pos('.act-dodge');

const tick = (ms) => page.waitForTimeout(ms);
const holdDpad = async (dx, dy, ms) => {
  await page.mouse.move(dpad.x + dpad.w / 2 + dx * dpad.w * 0.42, dpad.y + dpad.h / 2 + dy * dpad.h * 0.42);
  await page.mouse.down();
  await tick(ms);
  await page.mouse.up();
};
const tap = async (p) => { await page.touchscreen.tap(p.x, p.y); await tick(120); };

const startStocks = await page.evaluate(() => window.__arena.game.fighters.map((f) => f.stocks));
for (let i = 0; i < 6; i++) {
  await holdDpad(i % 2 ? 1 : -1, 0, 450);
  await tap(jump);
  await holdDpad(i % 3 === 0 ? 1 : -1, -1, 200);
  await tap(attack);
  await tap(special);
  if (i % 2 === 0) {
    await page.mouse.move(shield.x, shield.y);
    await page.mouse.down();
    await tick(180);
    await page.mouse.up();
    await tick(180);
  } else {
    await tap(dodge);
  }
  await tick(300);
}
const mid = await page.evaluate(() => ({
  phase: window.__arena.game.phase,
  stocks: window.__arena.game.fighters.map((f) => f.stocks),
  damage: window.__arena.game.fighters.map((f) => Math.round(f.damage)),
  held: [...window.__arena.input.touchHeld],
  pressedButtons: document.querySelectorAll('.touch-btn.pressed').length,
  projectiles: window.__arena.game.projectiles.length,
  finite: window.__arena.game.fighters.every((f) => Number.isFinite(f.x) && Number.isFinite(f.y) && Number.isFinite(f.damage)),
}));
console.log('mid-fight:', { startStocks, ...mid });

// Pause, restart from pause, verify clean state
await page.click('#battlePauseBtn');
await page.waitForTimeout(250);
await page.click('#restartBtn');
await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
await page.waitForTimeout(400);
console.log('after restart:', await page.evaluate(() => ({
  stocks: window.__arena.game.fighters.map((f) => f.stocks),
  touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
  held: [...window.__arena.input.touchHeld],
  screen: window.__arena.screen,
})));

// Pause, quit to title, verify touch UI hidden
await page.click('#battlePauseBtn');
await page.waitForTimeout(250);
await page.click('#quitBtn');
await page.waitForTimeout(400);
console.log('after quit:', await page.evaluate(() => ({
  screen: window.__arena.screen,
  touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
  pauseVisible: !document.querySelector('#battlePauseBtn').classList.contains('hidden'),
  touchMode: document.getElementById('app').classList.contains('touch-mode'),
})));
await page.screenshot({ path: join(outDir, '20-mobile-title-final.jpg'), type: 'jpeg', quality: 82 });
console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

import { createRequire } from 'node:module';
