const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
const browser = await chromium.launch({ headless: true });
const results = {};
for (const [name, w, h] of [['small', 320, 568], ['medium', 375, 667], ['tablet', 768, 1024]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(650);
  await page.evaluate(() => {
    window.__arena.startBattle({
      stocks: 3, difficulty: 2, stage: 'sky',
      slots: [
        { type: 'human', char: 'blaze' },
        { type: 'cpu', char: 'volt' },
        { type: 'cpu', char: 'glacier' },
        { type: 'cpu', char: 'sprout' },
      ],
    });
  });
  await page.waitForFunction(() => window.__arena.game.phase === 'fight', null, { timeout: 12000 });
  await page.waitForTimeout(400);
  results[name] = await page.evaluate(() => {
    const r = (s) => { const b = document.querySelector(s).getBoundingClientRect(); return { left: Math.round(b.left), top: Math.round(b.top), right: Math.round(b.right), bottom: Math.round(b.bottom), w: Math.round(b.width), h: Math.round(b.height) }; };
    const d = r('.touch-dpad'); const a = r('.touch-actions'); const hud = r('.hud-cards');
    return {
      viewport: [innerWidth, innerHeight],
      dpad: d, actions: a, hud,
      overlap: d.right > a.left,
      fits: d.left >= 0 && a.right <= innerWidth && d.bottom <= innerHeight && a.bottom <= innerHeight,
      clearOfHud: d.top > hud.bottom && a.top > hud.bottom,
      touchVisible: !document.querySelector('#touchControls').classList.contains('hidden'),
    };
  });
  results[name].errors = errors;
  await page.screenshot({ path: join(outDir, `21-touch-${name}.jpg`), type: 'jpeg', quality: 82 });
  await page.close();
}
console.log(JSON.stringify(results, null, 2));
await browser.close();

