import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const outDir = '/home/runner/work/Tester002/Tester002/screenshots';
const browser = await chromium.launch({ headless: true });
for (const [name, w, h] of [['390', 390, 844], ['320', 320, 568]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(650);
  await page.click('#customPlay');
  await page.waitForTimeout(700);
  const select = await page.evaluate(() => {
    const h = document.querySelector('#selectScreen .screen-heading h2').getBoundingClientRect();
    const s = document.querySelector('.system-buttons').getBoundingClientRect();
    return { heading: { left: Math.round(h.left), right: Math.round(h.right), top: Math.round(h.top), bottom: Math.round(h.bottom), h: Math.round(h.height) }, sys: { left: Math.round(s.left), top: Math.round(s.top) }, overlap: h.right > s.left && h.bottom > s.top };
  });
  await page.screenshot({ path: join(outDir, `30-select-${name}.jpg`), type: 'jpeg', quality: 82 });
  await page.click('#toStage');
  await page.waitForTimeout(500);
  const stage = await page.evaluate(() => {
    const h = document.querySelector('#stageScreen .screen-heading h2').getBoundingClientRect();
    const s = document.querySelector('.system-buttons').getBoundingClientRect();
    return { heading: { left: Math.round(h.left), right: Math.round(h.right), top: Math.round(h.top), bottom: Math.round(h.bottom), h: Math.round(h.height) }, sys: { left: Math.round(s.left), top: Math.round(s.top) }, overlap: h.right > s.left && h.bottom > s.top };
  });
  await page.screenshot({ path: join(outDir, `31-stage-${name}.jpg`), type: 'jpeg', quality: 82 });
  console.log(name, { select, stage, errors });
  await page.close();
}
await browser.close();
EOF
